"""Package only inspected own-model captures and private-native evidence hashes."""
import argparse,json,shutil,hashlib
from pathlib import Path

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--repo',default='.');args=ap.parse_args();repo=Path(args.repo).resolve();base=repo/'build';cap=base/'model-completion/metallic-hydrogen-chain/purifier-native-fitting-captures-03';integration=base/'hydrogen-integration-readback-04.json';visual=base/'purifier-native-visual-review-04.json';geometry=base/'purifier-native-fitting-readback-05.json'
 for p in (cap/'qa.json',cap/'reopen-qa.json',integration,geometry):
  if not json.loads(p.read_text())['passed']:raise RuntimeError('Gate failed '+str(p))
 review=json.loads(visual.read_text());assert review['status']=='agent_visual_pass_for_four_rotated_pipe_joins' and review['main_mod_loaded']
 source=repo/'art/source-to-3d/metallic-hydrogen-chain/water-purifier/v16-owner-accepted/water-purifier-v16.blend';assert sha(source)==json.loads(geometry.read_text())['source_sha256']==json.loads((cap/'capture.json').read_text())['source_sha256']
 for row in json.loads((cap/'capture.json').read_text())['frames']:
  if sha(cap/row['path'])!=row['sha256']:raise RuntimeError('Changed rendered frame')
 out=repo/'art/source-to-3d/metallic-hydrogen-chain/water-purifier/v17-native-rotated-fittings'
 if out.exists():raise FileExistsError('Preserve deliveries')
 out.mkdir(parents=True);capture_out=out/'captures';capture_out.mkdir();shutil.copytree(cap/'frames',capture_out/'frames')
 for name in ['master.blend','capture.json','qa.json','reopen-qa.json','contact-sheet.png']+[f'{state}-{size}.png' for state in ['idle','working'] for size in [64,128,256]]:shutil.copy2(cap/name,capture_out/name)
 inspect=out/'inspection';inspect.mkdir()
 for p in [integration,visual,geometry]:shutil.copy2(p,inspect/p.name)
 sprites=repo/'build/model-completion/metallic-hydrogen-chain/production-addon-v11-visible-fittings/tp-hydrogen-production_0.1.0/graphics/purifier';shutil.copytree(sprites,out/'native-sprites')
 (out/'README.md').write_text('''# Purifier V17 native rotated fittings\n\nPreserves the owner-accepted V16 source, camera and machine body. The native capture derivative moves the two **visible UV-surfaced** mouth assemblies rigidly and adds real constant-bore axial sleeves. Hidden historical donor collars remain untouched. This corrects the earlier adapter selecting hidden collars while moving visible bolts.\n\nFour idle plus 32 working captures, six atlases and the independently reopened editable master pass. The four-second source cycle is retained. Four-pose geometry checks verify unchanged meshes/body/camera, every rendered mouth world transform and 72 bounded bore rays. Actual main-mod pipe views were inspected in all four rotations: bolts remain seated, exposed front pipes meet the receivers, and rear pipes draw behind the vessel. These are agent-reviewed views, not owner acceptance or continuous manufacturing proof. Native game screenshots remain private; inspection records contain their hashes only.\n\nThe composed addon uses object depth and a whole-sprite shift of +4 native pixels. Its actual seven-machine line produces six collected contained pellets from only water, steel and electricity; continuous/reloaded histories match, electricity interruptions stop production, inert material is not revived, and live formation/sealing preserves condition and remaining lifetime. All seven native clocks pass a 32-second counter study. Production and counter sprites differ only within private counter masks. The main-mod native graphics/pipe prototype definitions match the graphical profile exactly.\n\n`native-sprites` contains clean sprites only. Rebuild the composed addon with `tools/fmpl/production_smoke/build_hydrogen_production_addon.py --purifier-capture <this directory>/captures --out <fresh candidate>`. The saved master and the source-capture manifest preserve the actual authoring/capture lineage. Use `purifier_native_fittings.py` for directional fitting reconstruction; the original accepted V16 file is not rewritten.\n\nOrdinary forge/assembler player controls and final economy tuning remain unfinished. Graphics-to-process/audio phase synchronization is not claimed. This checkpoint does not complete the full production-chain/reactor/building goal.\n''',encoding='utf-8')
 (out/'DELIVERY.json').write_text(json.dumps({'status':'agent-reviewed native fitting checkpoint; ordinary player UI remains open','accepted_source_sha256':sha(source),'capture_sha256':sha(capture_out/'capture.json'),'inspection_hashes':{p.name:sha(p) for p in inspect.iterdir()},'owner_approved':False,'files':{p.relative_to(out).as_posix():sha(p) for p in out.rglob('*') if p.is_file()}},indent=2)+'\n');print('PURIFIER_V17_CHECKPOINT',out)
if __name__=='__main__':main()
